use crate::{domain::{CreateColony,CreateHiveBox,CreateMeliponary,CreateSpecies,PlaceColony},history,production::{self,CreateProductionRecord},repository};use sqlx::{sqlite::SqlitePoolOptions,SqlitePool};
async fn p()->SqlitePool{let p=SqlitePoolOptions::new().max_connections(1).connect("sqlite::memory:").await.unwrap();sqlx::migrate!("../migrations").run(&p).await.unwrap();p}async fn seed(p:&SqlitePool)->(String,String){let m=repository::create_meliponary(p,CreateMeliponary{name:"M".into(),responsible_name:None,location:None,notes:None}).await.unwrap();let s=repository::create_species(p,CreateSpecies{common_name:"Jataí".into(),scientific_name:None,genus:None,notes:None}).await.unwrap();let b1=repository::create_box(p,CreateHiveBox{meliponary_id:m.id.clone(),code:"CX-001".into(),model:None,material:None,location_note:None,notes:None}).await.unwrap();let b2=repository::create_box(p,CreateHiveBox{meliponary_id:m.id.clone(),code:"CX-002".into(),model:None,material:None,location_note:None,notes:None}).await.unwrap();let c=repository::create_colony(p,CreateColony{meliponary_id:m.id,species_id:s.id,code:"JAT-001".into(),origin_type:None,origin_notes:None,installed_at:None,mother_colony_id:None,notes:None}).await.unwrap();repository::place_colony(p,PlaceColony{colony_id:c.id.clone(),box_id:b1.id.clone(),started_at:Some("2026-01-01 09:00:00".into()),reason:None,notes:None}).await.unwrap();repository::place_colony(p,PlaceColony{colony_id:c.id.clone(),box_id:b2.id,started_at:Some("2026-02-01 09:00:00".into()),reason:None,notes:None}).await.unwrap();(c.id,b1.id)}
#[tokio::test]async fn retrospective_harvest_keeps_box_from_that_date(){let p=p().await;let(c,b)=seed(&p).await;let r=production::create(&p,CreateProductionRecord{colony_id:c,harvested_at:Some("2026-01-15 12:00:00".into()),product_type:"honey".into(),quantity:120.0,unit:"ml".into(),purpose:Some("Consumo".into()),notes:None}).await.unwrap();assert_eq!(r.box_id.as_deref(),Some(b.as_str()));assert_eq!(r.box_code.as_deref(),Some("CX-001"));}
#[tokio::test]async fn rejects_invalid_product_type(){let p=p().await;let(c,_)=seed(&p).await;assert!(production::create(&p,CreateProductionRecord{colony_id:c,harvested_at:None,product_type:"royal_jelly".into(),quantity:10.0,unit:"g".into(),purpose:None,notes:None}).await.is_err());}
#[tokio::test]async fn rejects_non_positive_quantity(){let p=p().await;let(c,_)=seed(&p).await;assert!(production::create(&p,CreateProductionRecord{colony_id:c,harvested_at:None,product_type:"pollen".into(),quantity:0.0,unit:"g".into(),purpose:None,notes:None}).await.is_err());}
#[tokio::test]async fn production_appears_in_colony_timeline(){let p=p().await;let(c,_)=seed(&p).await;production::create(&p,CreateProductionRecord{colony_id:c.clone(),harvested_at:Some("2026-02-10 12:00:00".into()),product_type:"honey".into(),quantity:80.0,unit:"ml".into(),purpose:None,notes:Some("Colheita leve".into())}).await.unwrap();assert!(history::timeline_by_colony(&p,&c).await.unwrap().iter().any(|x|x.source_type=="production"));}
